CREATE TYPE "DiscordEmbedAuditAction" AS ENUM ('DRAFT_CREATED','DRAFT_EDITED','DRAFT_CLONED','DRAFT_IMPORTED','DRAFT_EXPORTED','TARGET_CHANGED','DRAFT_DELETED','PUBLISHED','PUBLICATION_UPDATED','PUBLICATION_DELETED');
CREATE TABLE "DiscordEmbedDraft" ("id" TEXT NOT NULL,"guildId" TEXT NOT NULL,"creatorDiscordUserId" TEXT NOT NULL,"name" TEXT NOT NULL,"payload" JSONB NOT NULL,"linkButtons" JSONB NOT NULL,"targetChannelId" TEXT,"version" INTEGER NOT NULL DEFAULT 1,"lastPublishedAt" TIMESTAMP(3),"deletedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "DiscordEmbedDraft_pkey" PRIMARY KEY ("id"));
CREATE TABLE "DiscordEmbedPublication" ("id" TEXT NOT NULL,"draftId" TEXT NOT NULL,"guildId" TEXT NOT NULL,"channelId" TEXT NOT NULL,"messageId" TEXT NOT NULL,"publishedByDiscordUserId" TEXT NOT NULL,"revisionUsed" INTEGER NOT NULL,"publishedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3),"deletedAt" TIMESTAMP(3),"deletedByDiscordUserId" TEXT,CONSTRAINT "DiscordEmbedPublication_pkey" PRIMARY KEY ("id"));
CREATE TABLE "DiscordEmbedAuditEvent" ("id" TEXT NOT NULL,"guildId" TEXT NOT NULL,"draftId" TEXT NOT NULL,"publicationId" TEXT,"actorDiscordUserId" TEXT NOT NULL,"action" "DiscordEmbedAuditAction" NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "DiscordEmbedAuditEvent_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "DiscordEmbedPublication_guildId_channelId_messageId_key" ON "DiscordEmbedPublication"("guildId","channelId","messageId"); CREATE INDEX "DiscordEmbedDraft_guildId_deletedAt_updatedAt_idx" ON "DiscordEmbedDraft"("guildId","deletedAt","updatedAt"); CREATE INDEX "DiscordEmbedPublication_draftId_publishedAt_idx" ON "DiscordEmbedPublication"("draftId","publishedAt"); CREATE INDEX "DiscordEmbedAuditEvent_guildId_draftId_createdAt_idx" ON "DiscordEmbedAuditEvent"("guildId","draftId","createdAt");
ALTER TABLE "DiscordEmbedPublication" ADD CONSTRAINT "DiscordEmbedPublication_draftId_fkey" FOREIGN KEY ("draftId") REFERENCES "DiscordEmbedDraft"("id") ON DELETE CASCADE; ALTER TABLE "DiscordEmbedAuditEvent" ADD CONSTRAINT "DiscordEmbedAuditEvent_draftId_fkey" FOREIGN KEY ("draftId") REFERENCES "DiscordEmbedDraft"("id") ON DELETE CASCADE; ALTER TABLE "DiscordEmbedAuditEvent" ADD CONSTRAINT "DiscordEmbedAuditEvent_publicationId_fkey" FOREIGN KEY ("publicationId") REFERENCES "DiscordEmbedPublication"("id") ON DELETE SET NULL;
